import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 11 One good turn deserves another","link":"/life/english/new-concept/book-2/unit-01/lesson-011"},"next":{"text":"第二册：实践与进步 · Lesson 13 The Greenwood Boys","link":"/life/english/new-concept/book-2/unit-01/lesson-013"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 11 One good turn deserves another","link":"/life/english/new-concept/book-2/unit-01/lesson-011"},"next":{"text":"第二册：实践与进步 · Lesson 13 The Greenwood Boys","link":"/life/english/new-concept/book-2/unit-01/lesson-013"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-012.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-012.md"}'),i={name:"life/english/new-concept/book-2/unit-01/lesson-012.md"};function l(s,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-12-goodbye-and-good-luck" tabindex="-1">第二册：实践与进步 · Lesson 12 Goodbye and good luck <a class="header-anchor" href="#第二册-实践与进步-·-lesson-12-goodbye-and-good-luck" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 12 Goodbye and good luck&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>送别朋友出海，码头上安排明确却仍有天气变数；练习区别行程安排与祝愿。本课的语言观察是：is leaving 表示已落实的出发安排；will enjoy 可以表达对未来体验的预测。日期相同不意味着所有动词都必须使用同一种将来形式。完成学习后，请写一个送别小段落，包含出发安排、礼物和到达后的行动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>harbour</td><td>/ˈhɑːbə/</td><td>n.</td><td>港口</td><td>leave the harbour</td></tr><tr><td>sail</td><td>/seɪl/</td><td>v.</td><td>航行</td><td>sail across a bay</td></tr><tr><td>voyage</td><td>/ˈvɔɪɪdʒ/</td><td>n.</td><td>航海旅行</td><td>a sea voyage</td></tr><tr><td>wave</td><td>/weɪv/</td><td>v.</td><td>挥手</td><td>wave goodbye</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>set off — 出发，可用 for 引出目的地</li><li>wave goodbye — 挥手告别</li></ul><h2 id="语法讲解-将来表达与安排" tabindex="-1">语法讲解：将来表达与安排 <a class="header-anchor" href="#语法讲解-将来表达与安排" aria-label="Permalink to &quot;语法讲解：将来表达与安排&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：is leaving 表示已落实的出发安排；will enjoy 可以表达对未来体验的预测。日期相同不意味着所有动词都必须使用同一种将来形式。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Our neighbour is sailing to the island on Friday.</p></blockquote><p>我们的邻居计划周五乘船前往那座岛。</p><p>is sailing 是现在进行时表将来安排，on Friday 明确日期，to the island 表示目的地。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 sailing to，弱读 to；把 on Friday 作为独立时间信息重读。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our neighbour is sailing to the island on Friday. We have bought a small gift for her. She will call us when she arrives.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个送别小段落，包含出发安排、礼物和到达后的行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：is sailing 是现在进行时表将来安排，on Friday 明确日期，to the island 表示目的地。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 on/at：The boat leaves ___ Friday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 星期几前使用 on。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>她将在什么时候打电话？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When she arrives.</p><p><strong>解析：</strong> when 从句用现在时表达将来，不表示她已经抵达。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>纠正：She will call when she will arrive.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She will call when she arrives.</p><p><strong>解析：</strong> 普通将来时间状语从句使用现在时。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来表达与安排。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-011">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-013">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{p as __pageData,b as default};
